using Erbe2.Gameplay.Inventory;
using Erbe2.Gameplay.Scenes;
using Erbe2.Gameplay.Scenes.Actions;

namespace Erbe2.Gameplay.Interaction;

/// <summary>
///     Applies the original scene-versus-inventory ownership rule and preserves the owner of blocking modal continuations.
/// </summary>
/// <typeparam name="TSceneObject">Active scene's local object enum.</typeparam>
internal sealed class InteractionDispatcher<TSceneObject> : ISceneInteractionDispatcher<TSceneObject>,
    IModalInteractionContinuation where TSceneObject : struct, Enum
{
    private readonly Interface _interface;
    private readonly InventoryActions _inventoryActions;
    private readonly ISceneInteractionDispatcher<TSceneObject> _sceneActions;
    private ModalOwner _modalOwner;

    /// <summary>
    ///     Composes one scene descriptor table with the global inventory descriptor table.
    /// </summary>
    /// <param name="sceneActions">Active scene-object handlers.</param>
    /// <param name="inventoryActions">Global item handlers bound to the active scene.</param>
    /// <param name="gameInterface">Lower page used to detect blocking continuations.</param>
    /// <remarks>IDA: <c>RunInteractionLoop</c> (<c>0x1583A</c>) and <c>NormalizeInteractionObjectOrder</c> (<c>0x15B1A</c>).</remarks>
    internal InteractionDispatcher(ISceneInteractionDispatcher<TSceneObject> sceneActions,
        InventoryActions inventoryActions,
        Interface gameInterface)
    {
        _sceneActions = sceneActions;
        _inventoryActions = inventoryActions;
        _interface = gameInterface;
    }

    /// <summary>
    ///     Resumes the exact table that opened a blocking option or information page.
    /// </summary>
    /// <param name="selectedOption">Selected option, or -1 after information pages.</param>
    /// <returns>The destination requested by the continuation, or null.</returns>
    /// <remarks>IDA: <c>SelectTextPageOption</c> (<c>0x1A512</c>) and <c>WaitForLeftMouseClick</c> (<c>0x15E38</c>).</remarks>
    SceneId? IModalInteractionContinuation.CompleteModal(int selectedOption)
    {
        var destination = _modalOwner switch
        {
            ModalOwner.Scene when _sceneActions is IModalInteractionContinuation continuation => continuation
                .CompleteModal(selectedOption),
            ModalOwner.Inventory => ((IModalInteractionContinuation)_inventoryActions).CompleteModal(selectedOption),
            _ => null
        };

        if (!_interface.IsModalVisible)
        {
            _modalOwner = ModalOwner.None;
        }

        return destination;
    }

    /// <summary>
    ///     Sends inventory-owned commands to the item table and all remaining commands to the active scene table.
    /// </summary>
    /// <param name="request">Normalized confirmed command.</param>
    /// <returns>The requested destination scene, or null.</returns>
    /// <remarks>IDA: <c>RunInteractionLoop</c> (<c>0x1583A</c>) and <c>NormalizeInteractionObjectOrder</c> (<c>0x15B1A</c>).</remarks>
    SceneId? ISceneInteractionDispatcher<TSceneObject>.Dispatch(InteractionRequest<TSceneObject> request)
    {
        _modalOwner = ModalOwner.None;
        SceneId? destination;
        if (request.InventoryItem is { } item)
        {
            destination = _inventoryActions.Dispatch(item, request);
            if (_interface.IsModalVisible)
            {
                _modalOwner = ModalOwner.Inventory;
            }
        }
        else if (request.SceneObject is not null)
        {
            destination = _sceneActions.Dispatch(request);
            if (_interface.IsModalVisible)
            {
                _modalOwner = ModalOwner.Scene;
            }
        }
        else
        {
            _interface.SetCommandText(InteractionMessages.InvalidAction);
            destination = null;
        }

        return destination;
    }

    private enum ModalOwner
    {
        None,
        Scene,
        Inventory
    }
}

